	public static void solve(FastScanner sc, PrintWriter out){
		int n = sc.nextInt();
		int x = sc.nextInt();

		int[] m = new int[n];

		long res = 0;

		for(int i = 0; i < n; i++) {
			m[i] = sc.nextInt();
			x-=m[i];
			res++;
		}

		int min = Arrays.stream(m).min().getAsInt();

		while(x-min >= 0) {
			x-=min;
			res++;
		}

		out.println(res);
	}

