			b[i] = Integer.parseInt(str[i]);
		}

		long ans = 0;
		for (int i = 0; i < n; i++) {
			if (a[i] > 0) {
				ans += Math.min(a[i], b[i]);
				int temp = a[i];
				a[i] -= b[i];
				b[i] -= temp;
			}

			if (a[i] <= 0 && b[i] > 0) {
				ans += Math.min(a[i + 1], b[i]);
				int temp1 = a[i + 1];
				a[i + 1] -= b[i];
				b[i] -= temp1;
			}
		}

