public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new java.io.InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        String[] input_str_array = br.readLine().split(" ");
        int[] input_array = new int[N];

        for(int i = 0; i < N; i++) {
            input_array[i] = Integer.parseInt(input_str_array[i]);
        }

        int[] dp = new int[N];
        dp[0] = 0;
        dp[1] = Math.abs(input_array[1] - input_array[0]);

        for(int i = 2; i < N; i++) {

            if(dp[i-2] + (Math.abs(input_array[i] - input_array[i-2])) > dp[i-1] + (Math.abs(input_array[i] - input_array[i-1]))) {
                dp[i] = dp[i-1] + (Math.abs(input_array[i] - input_array[i-1]));
            } else {
                dp[i] = dp[i-2] + (Math.abs(input_array[i] - input_array[i-2]));
            }

        }

        pw.println(dp[N-1]);

        pw.close();
        br.close();
    }
}

import java.util.*;
import java.io.*;

public class Main{

	public static void main(String[] args) throws IOException{
		// TODO Auto-generated method stub

		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));


	    int stoneCount = Integer.parseInt(reader.readLine());
        String str[] = reader.readLine().split(" ");
	    int stones[] = new int[stoneCount];

	    for(int i=0;i<stoneCount; i++) stones[i] = Integer.parseInt(str[i]);

	     int dp[]  = new int[stoneCount + 1];

	     for(int i=0; i<=stoneCount; i++) dp[i] = -1;

	    int minimumIncurred = solve(stones, 0, stoneCount, dp);

	    System.out.println(minimumIncurred);



	}

	public static int solve(int stones[], int i, int stoneCount, int dp[])
	{

		if(i==stoneCount-1)
			return 0;

		if(dp[i] != -1)
			return dp[i];
		int first = Integer.MAX_VALUE;
		int second = Integer.MAX_VALUE;
		if(i+1<stoneCount) 
		first = Math.abs(stones[i] - stones[i+1])+solve(stones, i+1, stoneCount, dp);
		if(i+2<stoneCount)
		second = Math.abs(stones[i] - stones[i+2])+ solve(stones, i+2, stoneCount, dp);
		dp[i] = Math.min(first, second);
		return Math.min(first, second);	
	}

}

