        Scanner sc = new Scanner(System.in);
        int[] selSort = new int[sc.nextInt()];

        for(int i = 0; i < selSort.length; i++){
            selSort[i] = sc.nextInt();
        }

        SelectionSort ss = new SelectionSort(selSort);
        ss.changeOfSNum();
        ss.outPutOfSNum();
        ss.outPutCount();
    }
