        n = reader.nextInt();
        k = reader.nextInt();
        h = new int[n];
        dp = new Integer[n];
        for(int i=0;i<n;i++){
            h[i] = reader.nextInt();
        }
        System.out.println(frogJump(0));
    }

    static int frogJump(int idx){
        if(idx == n-1){
            return 0;
        }
        if(dp[idx]!=null){
            return dp[idx];
        }
        int minCost = Integer.MAX_VALUE;
        for(int i=1;i<=k;i++) {
            if (idx + i < n) {
                int cost = Math.abs(h[idx] - h[idx + i]) + frogJump(idx + i);
                minCost = Math.min(minCost, cost);
            }
        }
        dp[idx] = minCost;
        return minCost;
    }
}

