            if (BinarySearch(s, t[i])) {
                count++;
            }
        }
        System.out.println(count);
    }

    static boolean BinarySearch(int[] a, int key) {
        int left = 0;
        int right = a.length;
        while (left < right) {
            int mid = (left + right) / 2;
            if (a[mid] == key) {
                return true;
            }
            else if (key < a[mid]) {
                right = mid;
            }
            else {
                left = mid + 1;
            }
        } 
        return false;
    }
}

