public class Main {
  static InputReader in;
  static PrintWriter out;

  static class Solution {
    void solve() throws IOException {
      int n = in.nextInt();
      int taropoint = 0;
      int hanakopoint = 0;
      String tarocard;
      String hanakocard;

      for (int i = 0; i < n; i++) {
        tarocard = in.next();
        hanakocard = in.next();

        if (!tarocard.equals(hanakocard)) {   
            for (int j = 0, min = Math.min(tarocard.length(), hanakocard.length());  j < min; j++) {
              if (tarocard.charAt(j) > hanakocard.charAt(j)) {
                taropoint += 3;
                break;
              } else if (tarocard.charAt(j) < hanakocard.charAt(j)){
                hanakopoint += 3;
                break;
              }

              if (j == min - 1) {
                if (min == tarocard.length()) {
                  hanakopoint +=3;
                  break;
                } 
                taropoint += 3;
              }
            }
        } else {
          taropoint++;
          hanakopoint++;
        }
      }

      out.println(taropoint + " " + hanakopoint);

//      End solve()
    }

//  End solution
  } 


  public static void main(String[] args) throws IOException {
    in = new InputReader(System.in);
    out = new PrintWriter(System.out);
    Solution solver = new Solution();
    solver.solve();
    out.close();
}

  static class InputReader {
    public BufferedReader br;
