		long K = ni();
		int N = ni();
		int[] a = na(N);
		long max = 0;
		for (int i = 1; i < N; i++)
			max = Math.max(max, a[i] - a[i - 1]);
		max = Math.max(max, K - a[N - 1] + a[0]);

		out.println(K - max);
