        BigInteger bi = BigInteger.ONE;
        BigInteger comp = new BigInteger("1000000000000000000");
        boolean over = false;

        for (int i = 0; i < n; i++) {
            long a = readLong();
            if (a == 0) {
                System.out.print(0);
                return;
            }

