      for (int i = 0; i < N; ++i){
        for (int j = 0; j < K[i]; ++j){
            like[A[i][j] -1]++; //K[i]番目の料理が好き
        }
      }
      for (int i = 0; i < M; ++i){  //各料理の「好きだ」と解答した人数を調べる
        if (like[i] == N){  //その料理を全員が好きであればカウント
            ++count;
        }
      }

      answer = count;
      return answer;
  }

  // 回答の表示
  void show(int answer) {
        System.out.println(answer);
  }

}

