     * 引数が平方数かどうか判定
     * @param pnum
     * @return 平方数の場合は"Yes"、それ以外は"No"
     */
    private static String checksqrt(double pnum) {
        // 引数の平方根を求める
        double n = Math.sqrt(pnum);
        // 引数を平方根で割った余りが0ならば平方数
        if (pnum % n == 0) {
            return "Yes";
        } else {
            return "No";
        }
    }

}

