		while (sc.hasNext()) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			System.out.println(GCD(a, b) + " " + 1l * a * b / GCD(a, b));
		}
		sc.close();
	}

	public static int GCD(int x, int y) {
		int tmp;
		while ((tmp = x % y) != 0) {
			x = y;
			y = tmp;
		}
		return y;
	}
}

