    public static boolean check(int target) {
      if (target % 4 == 0) {
        return true;
      }
      int i = 0;
      while(true) {
        int value = target - i * 4;
        if (value % 7 == 0) {
          return true;
        }
        if (value < 7) {
          return false;
        }
        i++;
      }
    }
}

