		int end = list.length - 1;
		while(start <= end)
		{
			int mid = ((start + end) / 2);

			if(list[mid] == n)
			{
				return true;
			} else if (list[mid] > n) {
				end = mid - 1;
			}else {
				start = mid + 1;
			}
		}

		return false;
	}
}

