      if(A>B){
        	while(b!=0){
        		too = (a%b);
        		a = b;
        		b =too;
        }
        //最小公倍数を求める(lcm=(A*B)/gcd)
       	System.out.println((A*B)/a); 
      }

      //Bが大きいときの最大公約数を求める
      else if(B>A){
          	while(a!=0){
      			too = (b%a);
      			b = a;
     			a =too;
          }
        //最小公倍数を求める
       	System.out.println((B*A)/b); 
      }
    }
}

