class Scanner {
	private static final int SPACE = (int)' ';
	private static final int LINE_END_0 = 13;
	private static final int LINE_END_1 = 10;
	private static final int BEFORE = -1;
	private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

	public String next(){
		StringBuilder sb = new StringBuilder();

		int length = BEFORE;
		readLoop: while(true) {
			try {
				int value = br.read();
				switch(value) {
				case LINE_END_1:
					if(length == BEFORE)
						break;

					if((int)sb.charAt(length) == LINE_END_0)
						sb.deleteCharAt(length);
				case SPACE:
					break readLoop;
				}
				sb.append((char)value);
				length++;

			} catch (IOException e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
			}
		}
		return sb.toString();
	}

	public String[] nextArray(int length) {
		String[] array = new String[length];
		for(int i = 0; i < length; i++)
			array[i] = next();
		return array;
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}

	public double[] nextDoubleArray(int length) {
		double[] array = new double[length];
		for(int i = 0; i < length; i++)
			array[i] = nextDouble();
		return array;
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public int[] nextIntArray(int length) {
		int[] array = new int[length];
		for(int i = 0; i < length; i++)
			array[i] = nextInt();
		return array;
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public long[] nextLongArray(int length) {
		long[] array = new long[length];
		for(int i = 0; i < length; i++)
			array[i] = nextLong();
		return array;
	}

	public boolean ready() {
		try {
			return br.ready();
		} catch (IOException e) {
			// TODO Auto-generated catch block
			e.printStackTrace();
		}
		return false;
	}
}

import java.util.Scanner;

public class Main {

	public static final int BIG_NUM  = 2000000000;
	public static final int MOD  = 1000000007;

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int H,W;

		H = sc.nextInt();
		W = sc.nextInt();

		int table[][] = new int[H+1][W+1];

		for(int row = 0; row < H; row++){
			for(int col = 0; col < W; col++){
				table[row][col] = sc.nextInt();
			}
		}

		for(int row = 0; row < H; row++){
			table[row][W] = 0;
			for(int col = 0; col < W; col++){
				table[row][W] += table[row][col];
			}
		}

		for(int col = 0; col <= W; col++){
			table[H][col] = 0;
			for(int row = 0; row < H; row++){
				table[H][col] += table[row][col];
			}
		}

		for(int row = 0; row <= H; row++){
			System.out.printf("%d", table[row][0]);
			for(int col = 1; col <= W; col++){
				System.out.printf(" %d", table[row][col]);
			}
			System.out.printf("\n");
		}
	}
}

