	private static int colorCode(int n){
		int[] rate = {1,400,800,1200,1600,2000,2400,2800,3200};
		int i;
		for(i=0;i<rate.length;i++){
			if(rate[i] <= n){
				continue;
			}else{
				break;
			}
		}
		return i-1;
	}
