		System.out.println(ans);
	}
	public static boolean checkRet(String s){
		int n;
		int len = s.length() - 1;
		if(len > 1){
			n = len / 2;
		}else{
			n = 1;
		}
		for(int i = 0;i < n;i++){
			if(s.charAt(i) != s.charAt(len - i)){
				return false;
			}
		}
		return true;
	}
}

