	void main() {

		int n=inp.nextInt();
		int k=inp.nextInt();
		int h[]=new int[n];
		for(int i=0;i<n;i++) {
			h[i]=inp.nextInt();
		}
		int dp[]=new int[n];
		Arrays.fill(dp, Integer.MAX_VALUE);
		dp[0]=0;
		for(int i=1;i<n;i++) {
			for(int j=1;j<=k && j<=i;j++) {
				dp[i]=Math.min(dp[i],dp[i-j]+ Math.abs(h[i]-h[i-j]));
			}
		}
		out.println(dp[n-1]);
	}



	static class FastReader { 
        BufferedReader br; 
        StringTokenizer st;
        public FastReader() { 
            br = new BufferedReader(new InputStreamReader(System.in)); 
        } 
        String next() { 
            while (st==null || !st.hasMoreElements()) { 
                try { 
                    st = new StringTokenizer(br.readLine()); 
                } 
                catch (IOException  e) { 
                    e.printStackTrace(); 
                } 
            } 
            return st.nextToken(); 
        } 
        int nextInt() { 
            return Integer.parseInt(next()); 
        } 
        long nextLong() { 
            return Long.parseLong(next()); 
        } 
        double nextDouble() { 
            return Double.parseDouble(next()); 
        } 
        String nextLine() { 
            String s=""; 
            try { 
                s=br.readLine(); 
            } 
            catch (IOException e) { 
                e.printStackTrace(); 
            } 
            return s; 
        } 
    } 


