		int N = sc.nextInt();
		int D = sc.nextInt();

		int x[][] = new int[N][D];

		for (int i = 0; i < N; i++) {
			for (int j = 0; j < D; j++) {
				x[i][j] = sc.nextInt();
			}
		}
		int ans =0;
		for (int i = 0; i < N; i++) {
			for (int j = i+1; j < N; j++) {

