					dis += (int) Math.pow(x[i][k]-x[j][k], 2);
				}
				for (int k = 0; k < 200; k++) {
					if (dis < Math.pow(k, 2)) {
						break;
					}
					if (dis == Math.pow(k, 2)) {
						ans++;
					}
				}
			}
		}
