			int[] B = new int[N];
			int[] C = new int[N - 1];
			for(int i = 0; i < N; i++) {
				A[i] = in.nextInt();
			}
			for(int i = 0; i < N; i++) {
				B[i] = in.nextInt();
			}
			for(int i = 0; i < N - 1; i++) {
				C[i] = in.nextInt();
			}
			int total = 0;
			int tmp = 0;
			for(int i = 0; i < N; i++) {
				total += B[A[i] - 1];
				if(i != 0) {
					if(A[i] - 1 == A[i - 1]) {
						total += C[A[i] - 2];
					}	
				}
			}
			System.out.println(total);

		}
	}

	static boolean permutation_2(String s, String t){
        if(s.length() != t.length()){
            return false;
        }

        int[] letters = new int[256]; //文字コードの仮定;

        char[] s_array = s.toCharArray();  
        for(char c:s_array){
            letters[c]++;
        }

        for(int i=0;i<t.length();i++){
            int c = (int)t.charAt(i);
            if(--letters[c] < 0){
                return false;
            }
        }
        return true;
    }

