    static class BUnevenNumbers {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            long n = in.nextInt();

            long answer = 0;
            for (int tens = 10; tens / 10 <= n; tens *= 100) {
                long max = tens - 1;
                long min = tens / 10;
                max = Math.min(max, n);

                answer += max - min + 1;
            }

            out.println(answer);
        }

    }

